def min_operations(s1: str, s2: str) -> int:
    if len(s1) != len(s2):
        return len(s1) - len(s2)

    dp = [0] * len(s2)
    for i in range(len(s2)):
        dp[i] = 0

    for i in range(len(s1)):
        for j in range(len(s2)):
            if s1[i] == s2[j]:
                dp[i] = min(dp[i], dp[j] + 1)
            else:
                dp[i] = dp[j] + 1

    return dp[-1]
```

