def four_sum(nums, target):
    n = len(nums)
    if n < 4:
        return []

    result = []

    for i in range(n - 3):
        for j in range(i + 1, n - 2):
            for k in range(j + 1, n - 1):
                for m in range(k + 1, n):
                    if nums[i] + nums[j] + nums[k] + nums[m] == target:
                        result.append([nums[i], nums[j], nums[k], nums[m]])

    return result
