def group_and_sort_orders(n, orders):
    senders = {}
    for i, order in enumerate(orders):
        sender = order.split(':')[0]
        if sender not in senders:
            senders[sender] = []
        senders[sender].append(orders[i])

    result = []
    for sender in sorted(senders.keys()):
        orders = senders[sender]
        for order in orders:
            receiver, items = order.split(':')
            items_str = ' '.join(items)
            result.append(f"{sender}\n{receiver}\n{items_str}")

    return len(senders) + '\n' + '\n'.join(result)
```

