def max_sum_k_consecutive(arr, k):
    n = len(arr)
    if n == 0:
        return 0
    if k < 1 or k > n:
        return 0
    max_sum = 0
    for i in range(n - k + 1):
        current_sum = sum(arr[i:i+k])
        max_sum = max(max_sum, current_sum)
    return max_sum
