def length_of_longest_substring(s: str) -> int:
    if not s:
        return 0
    last_seen = {}
    longest = 0
    current = 0
    for i, char in enumerate(s):
        if char in last_seen and last_seen[char] <= current:
            current = last_seen[char] + 1
        else:
            last_seen[char] = i
            current = i + 1
        longest = max(longest, current)
    return longest
```

