def max_area(heights):
    if not heights:
        return 0
    max_area = 0
    left = 0
    right = len(heights) - 1

    for i in range(len(heights)):
        current_height = heights[i]
        while left <= right:
            if heights[left] <= current_height:
                left += 1
            else:
                right -= 1
        max_area = max(max_area, current_height * (right - left + 1))

    return max_area
```

