def is_valid_expression(expression: str) -> bool:
    stack = []
    for char in expression:
        if char in "({[]}":
            stack.append(char)
        elif char in ")}]":
            if not stack:
                return False
            top = stack.pop()
            if char != top:
                return False
    return len(stack) == 0
