def manage_participants(queries):
    participants = []
    for query in queries:
        if query == "Add":
            name, score = query.split()
            participants.append((name, score))
        elif query == "Delete":
            name = query.split()[0]
            if name in participants:
                participants.remove(name)
        elif query == "Count":
            min_score, max_score = int(query.split()[0]), int(query.split()[1])
            count = sum(1 for name, score in participants if min_score <= score <= max_score)
            return count
    return []
